const raw = $input.item.json?.value ?? [];
const records = Array.isArray(raw) ? raw : [];

const matMap = {};
for (let i = 0; i < records.length; i++) {
  const r = records[i];
  const mat = r.MATERIAL ?? '';
  const qty = parseFloat(r.CONFDDELIVQTYINORDERQTYUNIT ?? 0);
  if (!mat) continue;
  if (!matMap[mat]) {
    matMap[mat] = { MATERIAL: mat, totalShipped: 0 };
  }
  matMap[mat].totalShipped += qty;
}

const output = Object.values(matMap);
return output.map(function(item) { return { json: item }; });

const workingObj = $('Stage 3 Trigger').item.json;
const customer         = workingObj.customer ?? {};
const items            = workingObj.items ?? [];
const salesHistory     = workingObj.salesHistory ?? [];
const openOrders       = workingObj.openOrders ?? [];
const opportunityItems = workingObj.opportunityItems ?? [];

// ── BLOCKLIST — SKUs never available for new orders ───────────────────────
const BLOCKLISTED_SKUS = [
  'A-100234-XX',
  'A-100235-XX'
];

// ── CUSTOMER PROFILE ──────────────────────────────────────────────────────
let profile = null;
try {
  const profileRows = $('Get Customer Profile').all();
  if (profileRows.length > 0 && profileRows[0].json && profileRows[0].json.customer_id) {
    profile = profileRows[0].json;
  }
} catch(e) { profile = null; }

const hasProfile = profile !== null;

// ── TOP SELLERS + MATERIAL LOOKUP ─────────────────────────────────────────
// These are global context — computed once from the full merged item list,
// unaffected by chunking, and included identically in every chunk's prompt.
const mergedItems = $input.all();
const matLookup = {};
const topSellersBySubFamily = {};

for (let i = 0; i < mergedItems.length; i++) {
  const row     = mergedItems[i].json;
  const mat     = row.MATERIAL    ?? '';
  const family  = (row.FAMILY ?? 'UNKNOWN').trim();
  const mgd2    = (row.MGD2   ?? '').trim();
  const desc    = row.DESCRIPTION ?? '';
  const shipped = row.totalShipped ?? 0;

  if (mat) matLookup[mat] = { family, mgd2, description: desc };

  if (!topSellersBySubFamily[family]) topSellersBySubFamily[family] = [];
  topSellersBySubFamily[family].push({ material: mat, description: desc, mgd2, totalShipped: shipped });
}

for (const family of Object.keys(topSellersBySubFamily)) {
  topSellersBySubFamily[family] = topSellersBySubFamily[family]
    .sort((a, b) => b.totalShipped - a.totalShipped)
    .slice(0, 5)
    .map((item, idx) => ({
      rank: idx + 1,
      material: item.material,
      description: item.description,
      mgd2: item.mgd2,
      totalShipped: item.totalShipped
    }));
}

// ── ITEM SUMMARY (filtered) ───────────────────────────────────────────────
const itemSummary = items
  .filter(i => {
    const family  = ((i.sacData?.family) ?? '').trim().toUpperCase();
    const mgd2    = ((i.sacData?.mgd2)   ?? '').trim().toUpperCase();
    const ats     = i.sacData?.qtyAvailableToSell;
    const price   = i.sacData?.netSellPrice   ?? 0;
    const shipped = i.sacData?.totalShippedQty ?? 0;
    const openOrd = i.sacData?.openOrderQty    ?? 0;
    const qoh     = i.qtyOnHand ?? 0;
    const mat     = i.mfrItemNumber ?? i.itemNo ?? i.material ?? '';

    if (BLOCKLISTED_SKUS.includes(mat)) return false;
    if (family === 'DISCONTINUED' || mgd2 === 'DISCONTINUED') return false;
    if (ats === null && price === 0 && shipped === 0 && openOrd === 0 && qoh === 0) return false;
    if ((ats ?? 0) > 0 && (ats ?? 0) < 10) return false;

    return true;
  })
  .map(i => {
    const mat    = i.mfrItemNumber ?? i.itemNo ?? i.material ?? '';
    const lookup = matLookup[mat] ?? {};
    return {
      itemNo:           mat,
      upc:              i.sacData?.upc              ?? '',
      description:      i.description ?? lookup.description ?? '',
      family:           (i.sacData?.family)           ?? lookup.family ?? '',
      mgd2:             (i.sacData?.mgd2)             ?? lookup.mgd2   ?? '',
      customerQOH:      i.qtyOnHand                   ?? 0,
      acmeATS:           i.sacData?.qtyAvailableToSell  ?? 0,
      netSellPrice:     i.sacData?.netSellPrice         ?? 0,
      openOrderQty:     i.sacData?.openOrderQty         ?? 0,
      totalShipped12mo: i.sacData?.totalShippedQty      ?? 0,
      hasOpenOrder:     i.sacData?.hasOpenOrder         ?? false
    };
  });

// ── LOW VOLUME DETECTION ──────────────────────────────────────────────────
// Computed against the FULL itemSummary before chunking, so slicing later
// doesn't skew this classification for any individual chunk.
const totalVelocity = itemSummary.reduce((sum, i) => {
  const soldThrough = Math.max(0, i.totalShipped12mo - i.customerQOH);
  return sum + (soldThrough / 52);
}, 0);
const avgWeeklyVelocity = itemSummary.length > 0 ? totalVelocity / itemSummary.length : 0;
const isLowVolume = !hasProfile && avgWeeklyVelocity < 0.5;

// ── PROFILE VALUES — with low-volume fallback ─────────────────────────────
const orderingHorizonDays  = profile?.ordering_horizon_days  ?? 63;
const targetWeeksOnHand    = profile?.target_weeks_on_hand   ?? (isLowVolume ? 15 : 9);
const orderFrequency       = profile?.order_frequency        ?? 'as-needed';
const preferredBrands      = profile?.preferred_brands       ?? null;
const excludedCategories   = profile?.excluded_categories    ?? null;
const customerGroup        = profile?.customer_group         ?? null;
const casePackPreference   = profile?.case_pack_preference   ?? 'both';
const notes                = profile?.notes                  ?? null;
const seasonalNotes        = profile?.seasonal_notes         ?? null;
const specialNotes         = profile?.special_notes          ?? null;
const minRecommendedQty    = profile?.min_recommended_qty    ?? 1;

// ── HISTORY BY SUB-FAMILY ─────────────────────────────────────────────────
// Global context — computed once, included identically in every chunk.
const historyBySubFamily = {};
for (const h of salesHistory) {
  const mat    = h.Material ?? h.MATERIAL ?? '';
  const lookup = matLookup[mat] ?? {};
  const sf     = lookup.family ?? h.FAMILY ?? 'UNKNOWN';
  if (!historyBySubFamily[sf]) historyBySubFamily[sf] = { totalQty: 0, totalAmount: 0 };
  const qty = parseFloat(h.ShippedQty ?? h.QUANT_BUN ?? 0);
  const amt = parseFloat(h.NetAmount  ?? h.netAmount ?? 0);
  historyBySubFamily[sf].totalQty    += qty;
  historyBySubFamily[sf].totalAmount += amt;
}

// ── OPEN ORDER SUMMARY ────────────────────────────────────────────────────
// Global context — computed once, included identically in every chunk.
const openOrderSubFamilies = [];
for (const o of openOrders) {
  const mat = o.Material ?? o.MATERIAL ?? '';
  const sf  = (matLookup[mat] ?? {}).family ?? 'UNKNOWN';
  if (!openOrderSubFamilies.includes(sf)) openOrderSubFamilies.push(sf);
}
const openOrderSummary = { totalLines: openOrders.length, subFamilies: openOrderSubFamilies };

// ── OPPORTUNITY ITEMS ─────────────────────────────────────────────────────
// Already capped at 30 and small — global context, included identically in
// every chunk rather than being split.
const opptySummary = opportunityItems
  .slice().sort((a, b) => (b.ats ?? 0) - (a.ats ?? 0))
  .filter(o => {
    const mat = o.material ?? o.MATERIAL ?? '';
    if (BLOCKLISTED_SKUS.includes(mat)) return false;
    if ((o.ats ?? 0) < 10) return false;
    return true;
  })
  .slice(0, 30)
  .map(o => {
    const mat    = o.material ?? o.MATERIAL ?? '';
    const lookup = matLookup[mat] ?? {};
    return {
      itemNo:       mat,
      upc:          o.upc          ?? '',
      description:  o.description ?? o.DESCRIPTION ?? lookup.description ?? '',
      family:       o.family ?? lookup.family ?? '',
      mgd2:         o.mgd2   ?? lookup.mgd2   ?? '',
      acmeATS:       o.ats    ?? o.ATS    ?? 0,
      netSellPrice: o.netSellPrice ?? 0,
      openOrderQty: o.openOrderQty ?? 0,
      hasOpenOrder: o.hasOpenOrder ?? false
    };
  });

// ── CHUNKING (only for genuinely large item summaries) ─────────────────────
// Mirrors the Stage 1 Build AI Parser Prompt pattern. Unlike Stage 1, the
// motivation isn't output-token overflow from itemSummary size alone — it's
// that raising the recommendation LIMIT on a single call (20/15 -> 40/30)
// blew the output cap. Splitting itemSummary into chunks lets each chunk
// independently propose up to the same proven-safe 20/15 limit from its own
// subset, so the total candidate pool grows across chunks without any
// single call's output growing past what's already known to fit safely.
// Accounts at or under CHUNK_THRESHOLD items are unaffected — they still
// produce exactly one chunk, one API call, identical to current behavior.
const CHUNK_THRESHOLD = 250;
const CHUNK_SIZE = 150;

const itemChunks = [];
if (itemSummary.length > CHUNK_THRESHOLD) {
  for (let i = 0; i < itemSummary.length; i += CHUNK_SIZE) {
    itemChunks.push(itemSummary.slice(i, i + CHUNK_SIZE));
  }
} else {
  itemChunks.push(itemSummary);
}
const totalChunks = itemChunks.length;

// ── SYSTEM PROMPT (shared across all chunks) ────────────────────────────────
const weeksLabel = targetWeeksOnHand >= 8
  ? `${targetWeeksOnHand} weeks (${Math.round(targetWeeksOnHand / 4.33)} months)`
  : `${targetWeeksOnHand} weeks`;

const casePackRule =
  casePackPreference === 'case-pack-only'
    ? 'This customer orders in case packs only — recommendedQty must be an exact multiple of casePack. Never recommend less than one full case pack.'
    : casePackPreference === 'less-than-case-pack-only'
    ? 'This customer orders in less-than-case-pack quantities only — recommendedQty should never be a full case pack multiple. Recommend individual units as needed.'
    : 'Recommend the exact quantity needed based on velocity and target stock level. Do not round to case pack multiples. Single units or any whole number quantity is acceptable.';

const profileLines = [
  `- Customer group: ${customerGroup ?? 'unknown'}`,
  `- Order frequency: ${orderFrequency}`,
  `- Ordering horizon: ${orderingHorizonDays} days — size recommendations to cover this window`,
  `- Target stock level: ${weeksLabel} on hand`,
  `- Case pack preference: ${casePackPreference}`,
  `- Minimum recommended quantity per SKU: ${minRecommendedQty} units — never recommend fewer than this regardless of velocity calculation`,
  `- Customer volume classification: ${isLowVolume ? 'LOW VOLUME — this is a small independent dealer with thin purchase history. Recommendations should be conservative and focused on top opportunity items. Note this in the narrative.' : 'standard'}`,
];
if (preferredBrands)    profileLines.push(`- Preferred brands: ${preferredBrands}`);
if (excludedCategories) profileLines.push(`- Excluded categories / products: ${excludedCategories}`);
if (seasonalNotes)      profileLines.push(`- Seasonal patterns: ${seasonalNotes}`);
if (specialNotes)       profileLines.push(`- Special notes: ${specialNotes}`);
if (notes)              profileLines.push(`- Additional notes: ${notes}`);

const systemPrompt = [
  "You are an expert wholesale sales analyst for Acme Manufacturing.",
  "You analyze customer inventory submissions and purchase history to generate intelligent reorder recommendations.",
  "",
  "OUTPUT FORMAT — THIS IS THE MOST CRITICAL INSTRUCTION:",
  "Your ENTIRE response must be a single valid JSON object and absolutely nothing else.",
  "Do NOT use markdown. Do NOT use asterisks (*). Do NOT use bullet points (- or •). Do NOT use numbered lists.",
  "Do NOT show calculations, working notes, reasoning steps, or any explanatory text anywhere in your response.",
  "Do NOT include any text before the opening { or after the closing }.",
  "Do NOT put any text between the availableNow array and the futureAvailability array.",
  "A single character outside the JSON structure will break the system. The response must start with { and end with } and contain nothing else.",
  "",
  "CRITICAL FIELD DEFINITIONS — read carefully before analyzing any data:",
  "- customerQOH: the quantity the CUSTOMER currently has on their shelves, taken directly from their inventory submission. This is their stock, not ours.",
  "- acmeATS: Acme's Available-to-Sell quantity — our warehouse stock available for immediate shipment. This is our stock, not theirs.",
  "- totalShipped12mo: total units Acme has shipped to this customer over the past 12 months (velocity indicator — never use directly as a target).",
  "- openOrderQty: quantity already on open or partially shipped sales orders for this SKU — already in the pipeline, counts as inventory the customer will have.",
  "These four fields are DIFFERENT numbers. Never substitute one for another in your rationale or narrative.",
  "",
  "Your output must be a single valid JSON object with exactly three keys:",
  "1. availableNow - array of order lines for items where acmeATS > 0 (Available for Immediate Delivery)",
  "2. futureAvailability - array of order lines for items where acmeATS <= 0 (Future Availability)",
  "3. narrative - a professional sales rep briefing (plain text, 100-150 words), OR an empty string if instructed below. No markdown, no asterisks, no bullet points — plain sentences only. Never use the double-quote character (\") anywhere — use '' (two single quotes) for inch measurements.",
  "",
  "IMPORTANT: Write availableNow first, then futureAvailability, then narrative. This ensures recommendations are never truncated.",
  "",
  "Each order line object in BOTH arrays must have exactly these keys with exactly these value types:",
  '{ "itemNo": "string", "upc": "string", "description": "string", "brand": "string", "subFamily": "string", "mgd2": "string", "casePack": number, "recommendedQty": number, "netSellPrice": number, "rationale": "string" }',
  "",
  "Field rules:",
  "- itemNo: Acme item number — use the exact itemNo from the submitted inventory data (string, never blank)",
  "- upc: UPC code — use the exact upc value from the submitted inventory item data (string, use empty string if not available)",
  "- description: product description — use '' (two single quotes) for inch measurements, never the double-quote character (\")",
  "- brand: one of Alpha, Bravo, or Charlie (string)",
  "- subFamily: FAMILY value (string)",
  "- mgd2: MGD2 value (string)",
  "- casePack: 5 for large items, 10 for all others (number — no quotes)",
  "- recommendedQty: positive whole number greater than 0 (number — no quotes)",
  "- netSellPrice: use the netSellPrice from the submitted data if available, else 0 (number — no quotes)",
  "- rationale: one sentence — must reference customerQOH when describing customer stock level — use '' for inch measurements, never the double-quote character (\")",
  "",
  "CUSTOMER ORDERING PROFILE:",
  ...profileLines,
  "",
  "Recommendation rules:",
  "- CRITICAL: Every item you include must be a genuine actionable recommendation. Omit any SKU you determine should be excluded — do not include it with a rationale explaining why it is excluded.",
  "- availableNow: include SKUs where acmeATS >= 10 that need replenishment. LIMIT to 20 items maximum, prioritized by sell-through velocity.",
  "- futureAvailability: include SKUs where acmeATS <= 0 that the customer carries or should carry. LIMIT to 15 items maximum, prioritized by purchase history.",
  "",
  `- MANDATORY PRE-SCREENING — run this exact decision tree on EVERY SKU before including it:`,
  `  Step 1: soldThrough = max(0, totalShipped12mo - customerQOH)`,
  `  Step 2: weeklyVelocity = soldThrough / 52`,
  `  Step 3: effectiveCoverage = (customerQOH + openOrderQty) / weeklyVelocity`,
  `     — if weeklyVelocity = 0, effectiveCoverage = 999 (skip unless opportunity item not currently carried by customer)`,
  `     — if effectiveCoverage >= ${targetWeeksOnHand}, EXCLUDE this SKU`,
  `  Step 4: recommendedQty = (${targetWeeksOnHand} x weeklyVelocity) - customerQOH - openOrderQty, rounded up, minimum ${minRecommendedQty}`,
  `     — if recommendedQty <= 0 before rounding, EXCLUDE this SKU`,
  `  Exception: opportunity items the customer does not currently carry bypass the velocity check — recommend minimum ${minRecommendedQty} unit(s) if acmeATS >= 10.`,
  "",
  `- This customer orders on a ${orderFrequency} cadence`,
  `- ${casePackRule}`,
  `- MINIMUM QUANTITY: Never recommend fewer than ${minRecommendedQty} units for any SKU.`,
  ...(preferredBrands    ? [`- Only recommend brands the customer carries: ${preferredBrands}`] : []),
  ...(excludedCategories ? [`- Do not recommend: ${excludedCategories}`] : []),
  "- When assessing inventory health by sub-family in the narrative, sum customerQOH across all submitted items in that sub-family.",
  "- totalShipped12mo is SKU-specific — do not aggregate across SKUs.",
  "- Prioritize top sellers per sub-family that align with this customer's purchase history.",
  "- Include opportunity items the customer does not carry but company top sellers suggest they should.",
  "- For futureAvailability items, you MUST populate itemNo with a specific Acme item number. Never leave itemNo blank or null.",
  "- CRITICAL — NO DOUBLE-QUOTE CHARACTERS: Never use \" anywhere in any string value. Always use '' (two single quotes) for inch measurements.",
  "- Return ONLY the raw JSON object. No preamble, no markdown, no explanation, no asterisks, no bullet points."
].join("\n");

// ── BUILD ONE OUTPUT ITEM PER CHUNK ─────────────────────────────────────────
// Only chunk index 0 is asked to write the narrative — it's the only chunk
// with any special status, and asking every chunk to write one would waste
// output tokens on 3-4 competing partial narratives that Combine would just
// have to discard anyway.
const outputItems = itemChunks.map((chunkItems, chunkIdx) => {
  const narrativeInstruction = totalChunks > 1
    ? (chunkIdx === 0
        ? `NOTE: This is chunk 1 of ${totalChunks} — only this chunk should write the "narrative" field (100-150 words) covering the account overall. `
        : `NOTE: This is chunk ${chunkIdx + 1} of ${totalChunks} — set "narrative" to an empty string "". Do not write a narrative for this chunk. `)
    : '';

  const userPrompt = [
    `CUSTOMER: ${customer.name ?? customer.customerName ?? 'Unknown'} (ID: ${customer.id ?? customer.customerId ?? 'Unknown'})`,
    `TODAY'S DATE: ${new Date().toISOString().split('T')[0]}`,
    `CUSTOMER VOLUME: ${isLowVolume ? `LOW VOLUME (avg weekly sell-through velocity: ${avgWeeklyVelocity.toFixed(2)} units/week across ${itemSummary.length} items — adjust recommendations accordingly)` : 'standard'}`,
    totalChunks > 1 ? `\n${narrativeInstruction}This chunk covers ${chunkItems.length} of the customer's ${itemSummary.length} total submitted items — the other chunks cover the rest, so only recommend from the items listed below in this chunk.` : '',
    "",
    "FIELD DEFINITIONS FOR ALL DATA BELOW:",
    "- customerQOH = customer's current shelf quantity (from their inventory file, NOT our stock)",
    "- acmeATS = Acme warehouse quantity available to sell (our stock, NOT the customer's)",
    "- totalShipped12mo = units we shipped to this customer in the last 12 months (velocity indicator — never use directly as target)",
    "- openOrderQty = quantity ALREADY ON ORDER and in the pipeline — treat as inventory the customer will have",
    "",
    totalChunks > 1
      ? `SUBMITTED INVENTORY — CHUNK ${chunkIdx + 1} OF ${totalChunks} (${chunkItems.length} items):`
      : `SUBMITTED INVENTORY (${chunkItems.length} items):`,
    JSON.stringify(chunkItems),
    "",
    "CUSTOMER 12-MONTH PURCHASE HISTORY BY SUB-FAMILY:",
    JSON.stringify(historyBySubFamily),
    "",
    "OPEN ORDERS:",
    JSON.stringify(openOrderSummary),
    "",
    "COMPANY-WIDE TOP 5 SELLERS BY SUB-FAMILY:",
    JSON.stringify(topSellersBySubFamily),
    "",
    "OPPORTUNITY ITEMS (acmeATS >= 10, not in customer submission, sorted by availability):",
    JSON.stringify(opptySummary),
    "",
    "Return your JSON recommendation now. Start with { and end with }. No other text."
  ].join("\n");

  return {
    json: {
      ...workingObj,
      topSellersBySubFamily,
      targetWeeksOnHand,
      isLowVolume,
      chunkIndex: chunkIdx,
      totalChunks: totalChunks,
      recommenderSystemPrompt: [
        {
          type: 'text',
          text: systemPrompt,
          cache_control: { type: 'ephemeral' }
        }
      ],
      recommenderMessages: [{ role: 'user', content: userPrompt }]
    },
    // Explicit pairedItem required: this node fans out many input items
    // (mergedItems) into just N chunk items with no natural 1:1
    // correspondence. Without this, downstream nodes running "Run Once for
    // Each Item" can't resolve $('Build Recommender Prompt Chunked').item
    // and throw "Paired item data ... is unavailable".
    pairedItem: 0
  };
});

return outputItems;

const raw = $input.first().json;

// ── TARGET WEEKS ON HAND ──────────────────────────────────────────────────
const workingObj = $('Stage 3 Trigger').item.json;

let profile = null;
try {
  const profileRows = $('Get Customer Profile').all();
  if (profileRows.length > 0 && profileRows[0].json && profileRows[0].json.customer_id) {
    profile = profileRows[0].json;
  }
} catch(e) { profile = null; }

// BUGFIX: raw is the Call Claude API httpRequest node's output, which has
// no "include input fields" option set — it returns only the Claude API
// response body (content/id/model/usage), never targetWeeksOnHand. That
// silently fell through to the hardcoded 4 below on every no-profile
// account, overriding the correct 9/15 split computed upstream. Read it
// back via the node reference instead, same pattern already used a few
// lines below for chunkIndex/totalChunks.
const targetWeeksOnHand = $('Build Recommender Prompt Chunked').item.json.targetWeeksOnHand
  ?? profile?.target_weeks_on_hand
  ?? 4;

const minRecommendedQty = profile?.min_recommended_qty ?? 1;

// ── CHUNK METADATA ─────────────────────────────────────────────────────────
// Mirrors the Stage 1 Parse & Validate API Response pattern — read chunk
// position from the corresponding Build Recommender Prompt output item
// rather than assuming it survived HTTP node passthrough.
const chunkIndex  = $('Build Recommender Prompt Chunked').item.json.chunkIndex  ?? 0;
const totalChunks = $('Build Recommender Prompt Chunked').item.json.totalChunks ?? 1;

// ── ITEM LOOKUP ───────────────────────────────────────────────────────────
const itemLookup = {};
for (const item of (workingObj.items ?? [])) {
  const key = item.mfrItemNumber ?? item.itemNo ?? item.material ?? '';
  if (!key) continue;
  itemLookup[key] = {
    customerQOH:      item.qtyOnHand                ?? 0,
    totalShipped12mo: item.sacData?.totalShippedQty ?? 0,
    openOrderQty:     item.sacData?.openOrderQty    ?? 0
  };
}

// ── EXTRACT CLAUDE RESPONSE ───────────────────────────────────────────────
const apiResponse = raw.claude_response ?? raw;
const contentBlocks = apiResponse?.content ?? [];

let jsonText = null;
for (let i = contentBlocks.length - 1; i >= 0; i--) {
  const block = contentBlocks[i];
  if (block.type === 'text' && block.text) {
    const match = block.text.match(/```json\s*([\s\S]*?)```/g);
    if (match) {
      jsonText = match[match.length - 1].replace(/```json\s*/g, '').replace(/```/g, '').trim();
      break;
    }
    const trimmed = block.text.trim();
    if (trimmed.startsWith('{')) {
      jsonText = trimmed;
      break;
    }
  }
}

if (!jsonText) {
  throw new Error(`No JSON found in Claude response (chunk ${chunkIndex + 1} of ${totalChunks})`);
}

// ── SANITIZE ──────────────────────────────────────────────────────────────
// Step 1a: Strip asterisks/bullets appearing BEFORE quoted property names.
jsonText = jsonText.replace(/[*•]\s*(?="[a-zA-Z])/g, '');

// Step 1b: Strip asterisks/bullets appearing AFTER values before comma/brace.
jsonText = jsonText.replace(/(["\d])[*•]+\s*(?=[,}\]])/g, '$1');

// Step 2: Scan character by character — escape control chars inside strings.
// Single quotes inside strings are valid JSON and must NOT be touched.
function sanitizeJson(text) {
  let out = '';
  let inStr = false;
  let esc = false;
  for (let i = 0; i < text.length; i++) {
    const ch = text[i];
    const code = text.charCodeAt(i);
    if (esc) { out += ch; esc = false; continue; }
    if (ch === '\\') { out += ch; esc = true; continue; }
    if (ch === '"') { inStr = !inStr; out += ch; continue; }
    if (inStr && code < 0x20) {
      if (ch === '\n') { out += '\\n'; continue; }
      if (ch === '\r') { out += '\\r'; continue; }
      if (ch === '\t') { out += '\\t'; continue; }
      out += '\\u' + code.toString(16).padStart(4, '0');
      continue;
    }
    out += ch;
  }
  return out;
}

jsonText = sanitizeJson(jsonText);

// Step 3: Fix unquoted property names outside string values.
// Only fires when a property key has no quotes — safe because it only
// matches identifiers immediately after { or , followed by a colon.
jsonText = jsonText.replace(/([{,]\s*)([a-zA-Z_][a-zA-Z0-9_]*)(\s*:)/g, (match, before, key, colon) => {
  // Skip if already quoted — check if key is preceded by a quote
  return `${before}"${key}"${colon}`;
});

let parsed;
try {
  parsed = JSON.parse(jsonText);
} catch(e) {
  throw new Error(`JSON parse failed (chunk ${chunkIndex + 1} of ${totalChunks}): ${e.message}`);
}

// ── VALID ITEM NUMBER CHECK ───────────────────────────────────────────
function isValidItemNo(itemNo) {
  if (!itemNo || typeof itemNo !== 'string') return false;
  const s = itemNo.trim();
  if (s.length < 5) return false;
  if (s.includes(' ')) return false;
  if (/^A-/.test(s)) return true;
  if (/^9[0-9A-Z]/.test(s)) return true;
  if (/^\d{3}-\d{4}-\d{2}$/.test(s)) return true;
  if (/^(BR|BX)/.test(s)) return true;
  if (/^CH/.test(s)) return true;
  if (/^(ACC|KIT)/.test(s)) return true;
  if (/^77\d{7}$/.test(s)) return true;
  return false;
}

// ── EXCLUSION PHRASES ─────────────────────────────────────────────────────
const EXCLUSION_PHRASES = [
  'adequately stocked', 'already covered', 'already at target',
  'no replenishment needed', 'no reorder needed',
  'does not need replenishment', 'does not require replenishment',
  'sufficient stock', 'sufficient inventory', 'overstocked',
  'above target', 'exceeds target', 'meets target', 'at target',
  'no action needed'
];

function isExcluded(line) {
  const rationale = (line.rationale ?? '').toLowerCase();
  return EXCLUSION_PHRASES.some(phrase => rationale.includes(phrase));
}

// ── COVERAGE CLASSIFICATION ────────────────────────────────────────────────
// Independently recomputes the EXACT recommendedQty formula from the
// recommender's own system prompt (Step 3/Step 4 of the mandatory
// pre-screening) using the deterministic itemLookup data, instead of
// trusting Claude's arithmetic.
//
//   NOT_IN_SUBMISSION — item isn't in this customer's submitted items at all (opportunity item — not judged by this formula)
//   NEVER_CARRIED     — customerQOH = 0 AND shipped12mo = 0 — no history to judge; prompt's own stated exception, bypasses the formula
//   FAILS_FORMULA     — recomputed recommendedQty <= 0 — customer is already covered by QOH + open orders relative to target
//   PASSES            — recomputed recommendedQty > 0 — genuinely needs replenishment
function classifyCoverage(line) {
  if (!itemLookup[line.itemNo]) {
    return { exclude: false, reason: 'NOT_IN_SUBMISSION' };
  }

  const data           = itemLookup[line.itemNo];
  const customerQOH    = data.customerQOH      ?? 0;
  const shipped12mo    = data.totalShipped12mo  ?? 0;
  const openOrderQty    = data.openOrderQty      ?? 0;

  if (customerQOH === 0 && shipped12mo === 0) {
    return { exclude: false, reason: 'NEVER_CARRIED' };
  }

  const soldThrough    = Math.max(0, shipped12mo - customerQOH);
  const weeklyVelocity = soldThrough / 52;
  const rawRecQty       = (targetWeeksOnHand * weeklyVelocity) - customerQOH - openOrderQty;

  if (rawRecQty <= 0) {
    return {
      exclude: true,
      reason: 'FAILS_FORMULA',
      rawRecQty,
      weeklyVelocity,
      customerQOH,
      shipped12mo,
      openOrderQty
    };
  }

  return {
    exclude: false,
    reason: 'PASSES',
    correctedRecQty: Math.max(minRecommendedQty, Math.ceil(rawRecQty)),
    weeklyVelocity,
    customerQOH,
    shipped12mo,
    openOrderQty
  };
}

// ── DEDUP ─────────────────────────────────────────────────────────────────
function dedupByItemNo(lines) {
  const seen = new Set();
  return lines.filter(line => {
    if (!line.itemNo || seen.has(line.itemNo)) return false;
    seen.add(line.itemNo);
    return true;
  });
}

// ── PROCESS ARRAYS ────────────────────────────────────────────────────────
const availableNowClassified = (parsed.availableNow ?? [])
  .filter(line => isValidItemNo(line.itemNo))
  .filter(line => !isExcluded(line))
  .map(line => ({ line, classification: classifyCoverage(line) }));

const futureAvailabilityClassified = (parsed.futureAvailability ?? [])
  .filter(line => isValidItemNo(line.itemNo))
  .filter(line => !isExcluded(line))
  .map(line => ({ line, classification: classifyCoverage(line) }));

console.log(`[chunk ${chunkIndex + 1}/${totalChunks}] availableNow breakdown:`, JSON.stringify(
  availableNowClassified.map(x => ({ itemNo: x.line.itemNo, ...x.classification }))
));
console.log(`[chunk ${chunkIndex + 1}/${totalChunks}] futureAvailability breakdown:`, JSON.stringify(
  futureAvailabilityClassified.map(x => ({ itemNo: x.line.itemNo, ...x.classification }))
));

let availableNow = dedupByItemNo(
  availableNowClassified
    .filter(x => !x.classification.exclude)
    .map(x => x.line)
);
const availableNowKeys = new Set(availableNow.map(l => l.itemNo));

let futureAvailability = dedupByItemNo(
  futureAvailabilityClassified
    .filter(x => !x.classification.exclude)
    .map(x => x.line)
    .filter(line => !availableNowKeys.has(line.itemNo))
);

// Only chunk 0 was instructed to write a real narrative — other chunks
// were told to return an empty string. Combine will only keep chunk 0's.
const aiNarrative = parsed.narrative ?? parsed.aiNarrative ?? '';

// ── OUTPUT ────────────────────────────────────────────────────────────────
return [{
  json: {
    ...workingObj,
    aiNarrative,
    availableNow,
    futureAvailability,
    targetWeeksOnHand,
    chunkIndex,
    totalChunks
  }
}];

// This node must run in "Run Once for All Items" mode — it needs to see
// every chunk's parsed output at once to merge them into a single working
// object before the rest of Stage 3 proceeds. For accounts under the
// CHUNK_THRESHOLD in Build Recommender Prompt, this receives exactly 1 item
// and simply passes it through unchanged (the merge logic is a no-op with
// only one chunk).
const allChunks = $input.all().map(i => i.json);
if (allChunks.length === 0) throw new Error('Combine Recommender Chunks FATAL: no chunk data received.');

// ── DEDUP ACROSS CHUNKS ─────────────────────────────────────────────────────
// Chunks are disjoint slices of itemSummary, so the same itemNo shouldn't
// legitimately appear in two chunks' availableNow/futureAvailability — but
// dedup anyway as a safety net (e.g. against a hallucinated itemNo that
// happens to collide, or an opportunity item both chunks independently
// picked up since opportunity items aren't chunk-scoped).
function dedupByItemNo(lines) {
  const seen = new Set();
  return lines.filter(line => {
    if (!line.itemNo || seen.has(line.itemNo)) return false;
    seen.add(line.itemNo);
    return true;
  });
}

let combinedAvailableNow = dedupByItemNo(
  allChunks.flatMap(chunk => chunk.availableNow ?? [])
);
const availableNowKeys = new Set(combinedAvailableNow.map(l => l.itemNo));

let combinedFutureAvailability = dedupByItemNo(
  allChunks
    .flatMap(chunk => chunk.futureAvailability ?? [])
    .filter(line => !availableNowKeys.has(line.itemNo))
);

// ── NARRATIVE ────────────────────────────────────────────────────────────
// Only chunk 0 was instructed to write a real narrative in the prompt —
// every other chunk was told to return an empty string. Take the first
// non-empty one found, defaulting to chunk 0's regardless.
const chunk0 = allChunks.find(c => (c.chunkIndex ?? 0) === 0) ?? allChunks[0];
const aiNarrative = allChunks.find(c => (c.aiNarrative ?? '').trim().length > 0)?.aiNarrative
  ?? chunk0.aiNarrative
  ?? '';

// ── SPARSE-ACCOUNT FLOOR (only fires when recommendations are genuinely thin) ──
// This is deliberately gated behind SPARSE_THRESHOLD so it NEVER touches an
// account that already has a healthy recommendation count — it only ever
// ADDS lines (never removes or replaces anything), and it only runs at all
// when the AI's own output came back sparse, like the Chattanooga case that
// prompted this (a handful of recommendations against 100+ real opportunities).
// An account with, say, 8 solid recommendations and 0 opportunity items is
// left completely untouched — this is not a general-purpose opportunity
// quota, it's a safety net for near-empty results specifically.
const SPARSE_THRESHOLD = 5;      // if total recommendations are below this, the account is considered sparse
const FLOOR_MIN_TOTAL = 10;      // target total once backfill is triggered
const FLOOR_MIN_OPPORTUNITY = 5; // target opportunity-sourced count once backfill is triggered
const MIN_OPPORTUNITY_ATS = 10;  // mirrors the prompt's own opportunity-item eligibility threshold

// Same blocklist as Build Recommender Prompt Chunked — kept in sync
// manually since this node has no access to that node's local constant.
const BLOCKLISTED_SKUS = [
  'A-100234-XX',
  'A-100235-XX'
];

let totalCount = combinedAvailableNow.length + combinedFutureAvailability.length;
const isSparse = totalCount < SPARSE_THRESHOLD;

const backfillLog = [];

if (isSparse) {
  const submittedItemNos = new Set(
    (chunk0.items ?? [])
      .map(i => i.mfrItemNumber ?? i.itemNo ?? i.material)
      .filter(Boolean)
  );

  function isOpportunitySourced(itemNo) {
    return !submittedItemNos.has(itemNo);
  }

  let opportunityCount = [...combinedAvailableNow, ...combinedFutureAvailability]
    .filter(line => isOpportunitySourced(line.itemNo)).length;

  const usedItemNos = new Set([...combinedAvailableNow, ...combinedFutureAvailability].map(l => l.itemNo));

  const pool = (chunk0.opportunityItems ?? [])
    .filter(o => (o.ats ?? 0) >= MIN_OPPORTUNITY_ATS)
    .filter(o => !BLOCKLISTED_SKUS.includes(o.material))
    .filter(o => !usedItemNos.has(o.material))
    .filter(o => !submittedItemNos.has(o.material))
    .sort((a, b) => (b.ats ?? 0) - (a.ats ?? 0));

  for (const o of pool) {
    if (totalCount >= FLOOR_MIN_TOTAL && opportunityCount >= FLOOR_MIN_OPPORTUNITY) break;

    const line = {
      itemNo:      o.material,
      custQOH:     0,
      wklyVel:     0,
      currWOS:     0,
      targetWOS:   chunk0.targetWeeksOnHand ?? 4,
      targetQty:   1,
      onOrderQty:  o.openOrderQty ?? 0,
      recQty:      1,
      netPrice:    o.netSellPrice ?? 0,
      rationale:   `Auto-added by sparse-recommendation floor: Acme has ${o.ats} units available and this SKU is not currently carried by the customer; included because this account's recommendations came back sparse (${totalCount} before backfill).`,
      source:      'floor-backfill'
    };

    combinedAvailableNow.push(line);
    usedItemNos.add(o.material);
    totalCount++;
    opportunityCount++;
    backfillLog.push(o.material);
  }

  if (totalCount < FLOOR_MIN_TOTAL || opportunityCount < FLOOR_MIN_OPPORTUNITY) {
    console.log(`[floor-backfill] Sparse account, but opportunity pool exhausted before reaching floor. Final: total=${totalCount}, opportunity=${opportunityCount}`);
  }
  if (backfillLog.length > 0) {
    console.log(`[floor-backfill] Account was sparse (< ${SPARSE_THRESHOLD} total) — added ${backfillLog.length} item(s):`, JSON.stringify(backfillLog));
  }
}

// ── OUTPUT ───────────────────────────────────────────────────────────────
const workingObject = {
  ...chunk0,
  availableNow: combinedAvailableNow,
  futureAvailability: combinedFutureAvailability,
  aiNarrative,
  chunksProcessed: allChunks.length
};

// chunkIndex/totalChunks were only relevant during processing — strip them
// from the final combined object so they don't leak into the report.
delete workingObject.chunkIndex;
delete workingObject.totalChunks;

return { json: workingObject };
